/**
 * Catalog of the insertable icon library (CORE-ICON-001): the manifest of
 * `assets/icons/library/` (original BlueOffice drawings, generated by
 * `scripts/gen-icon-library.mjs`) and its search. The SVG documents and the manifest live
 * in a separate chunk that `loadIconLibrary` fetches on first use.
 */
import { foldText } from '../symbols/catalog';

export type IconLocale = 'vi' | 'en';

export interface IconLibraryEntry {
  id: string;
  category: string;
  /** File name under `assets/icons/library/`. */
  file: string;
  name: Record<IconLocale, string>;
  /** Search words; `vi` holds the accented and the unaccented spelling. */
  keywords: Record<IconLocale, string[]>;
}

export interface IconLibraryCategory {
  id: string;
  name: Record<IconLocale, string>;
}

export interface IconLibraryManifest {
  version: number;
  license: string;
  /** Side of the drawing grid (viewBox units). */
  grid: number;
  categories: IconLibraryCategory[];
  icons: IconLibraryEntry[];
}

export interface IconLibrary {
  manifest: IconLibraryManifest;
  /** SVG document of an icon id. */
  svg: (id: string) => string | undefined;
}

/** Locale of the icon names for a UI language tag (`vi-VN` → `vi`, anything else → `en`). */
export function iconLocale(language: string | undefined): IconLocale {
  return language?.toLowerCase().startsWith('vi') ? 'vi' : 'en';
}

const parts = (s: string) => s.split(/[\s-]+/);

/** How well one query word matches an icon; lower is better, `null` = no match. */
function wordScore(
  entry: IconLibraryEntry,
  names: readonly string[],
  keywords: readonly string[],
  w: string,
): number | null {
  let best = Infinity;
  for (const n of names) {
    if (n === w) best = Math.min(best, 0);
    else if (n.startsWith(w)) best = Math.min(best, 1);
    else if (parts(n).some((p) => p.startsWith(w))) best = Math.min(best, 2);
    else if (n.includes(w)) best = Math.min(best, 5);
  }
  for (const k of keywords) {
    if (k === w) best = Math.min(best, 3);
    else if (parts(k).some((p) => p.startsWith(w))) best = Math.min(best, 4);
    else if (k.includes(w)) best = Math.min(best, 6);
  }
  if (entry.id.includes(w)) best = Math.min(best, 6);
  return Number.isFinite(best) ? best : null;
}

/** Bonus (negative) when the whole query is a name or a keyword, or starts / is part of one. */
function phraseScore(
  names: readonly string[],
  keywords: readonly string[],
  phrase: string,
): number {
  if (names.includes(phrase)) return -100;
  if (names.some((n) => n.startsWith(phrase))) return -50;
  if (keywords.includes(phrase)) return -30;
  if (names.some((n) => n.includes(phrase))) return -20;
  if (keywords.some((k) => k.includes(phrase))) return -10;
  return 0;
}

/**
 * Icons matching `query` (every word must match the Vietnamese or English name, a keyword
 * or the id — from its start or the start of one of its words; case and Vietnamese diacritics
 * are ignored, so "mui ten" finds "Mũi tên"), best matches first: the whole query as a name,
 * then as a keyword, then word by word. An empty query lists the icons in manifest order. `category`
 * restricts the result to one category id.
 */
export function searchIcons(
  icons: readonly IconLibraryEntry[],
  query: string,
  category?: string | null,
): IconLibraryEntry[] {
  const pool = category ? icons.filter((i) => i.category === category) : [...icons];
  const words = foldText(query).split(' ').filter(Boolean);
  if (words.length === 0) return pool;
  const scored: { entry: IconLibraryEntry; score: number; at: number }[] = [];
  pool.forEach((entry, at) => {
    const names = [foldText(entry.name.vi), foldText(entry.name.en)];
    const keywords = [...entry.keywords.vi, ...entry.keywords.en].map(foldText);
    let score = phraseScore(names, keywords, words.join(' '));
    for (const w of words) {
      const s = wordScore(entry, names, keywords, w);
      if (s === null) return;
      score += s;
    }
    scored.push({ entry, score, at });
  });
  return scored.sort((a, b) => a.score - b.score || a.at - b.at).map((s) => s.entry);
}

let cached: Promise<IconLibrary> | null = null;

/** The icon library; its chunk (manifest + SVG documents) is fetched once, on first use. */
export function loadIconLibrary(): Promise<IconLibrary> {
  cached ??= import('./bundle').then((m) => m.ICON_LIBRARY);
  return cached;
}
